package com.aaliyun.leadnews.behavior.config;
import com.aaliyun.leadnews.model.behavior.BehaviorEvent;import org.apache.kafka.clients.admin.NewTopic;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.TopicPartition;import org.apache.kafka.common.serialization.StringSerializer;import org.springframework.boot.autoconfigure.kafka.KafkaProperties;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;import org.springframework.core.io.ClassPathResource;import org.springframework.data.redis.core.script.DefaultRedisScript;import org.springframework.kafka.core.*;import org.springframework.kafka.listener.*;import org.springframework.kafka.support.serializer.JsonSerializer;import org.springframework.util.backoff.FixedBackOff;import java.util.*;
@Configuration @EnableConfigurationProperties(BehaviorProperties.class) public class BehaviorConfiguration {
 @Bean DefaultRedisScript<java.util.List> likeScript(){return script("lua/like.lua",java.util.List.class);}@Bean DefaultRedisScript<java.util.List> unlikeScript(){return script("lua/unlike.lua",java.util.List.class);}@Bean DefaultRedisScript<Long> viewScript(){return script("lua/view.lua",Long.class);}@Bean DefaultRedisScript<Long> initializeCounterScript(){return script("lua/initialize-counter.lua",Long.class);}@Bean DefaultRedisScript<Long> initializeLikeScript(){return script("lua/initialize-like.lua",Long.class);}private <T>DefaultRedisScript<T> script(String p,Class<T> t){DefaultRedisScript<T>s=new DefaultRedisScript<>();s.setLocation(new ClassPathResource(p));s.setResultType(t);return s;}
 @Bean NewTopic behaviorTopic(BehaviorProperties p){return new NewTopic(p.getTopic(),3,(short)1);}@Bean NewTopic behaviorDltTopic(BehaviorProperties p){return new NewTopic(p.getDltTopic(),3,(short)1);}
 @Bean KafkaTemplate<String,BehaviorEvent> behaviorKafkaTemplate(KafkaProperties properties){Map<String,Object> c=new HashMap<>(properties.buildProducerProperties());c.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);c.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,JsonSerializer.class);return new KafkaTemplate<>(new DefaultKafkaProducerFactory<>(c));}
 @Bean DefaultErrorHandler behaviorErrorHandler(KafkaTemplate<String,BehaviorEvent> k,BehaviorProperties p){return new DefaultErrorHandler(new DeadLetterPublishingRecoverer(k,(r,e)->new TopicPartition(p.getDltTopic(),r.partition())),new FixedBackOff(1000,2));}
}
